const path = require('path');

(async () => {
  const browser = await puppeteer.launch({
    headless: true,
    args: ['--no-sandbox', '--disable-setuid-sandbox', '--disable-dev-shm-usage']
  });
  const page = await browser.newPage();
  await page.setViewport({ width: 1080, height: 1920, deviceScaleFactor: 2 });

  const htmlPath = 'file://' + path.resolve('/app/output/poster.html');
  await page.goto(htmlPath, { waitUntil: 'networkidle0', timeout: 30000 });

  // Wait for fonts
  await page.evaluate(() => document.fonts?.ready);
  await new Promise(r => setTimeout(r, 1000));

  // Get actual body height
  const bodyHeight = await page.evaluate(() => document.body.scrollHeight);
  await page.setViewport({ width: 1080, height: bodyHeight, deviceScaleFactor: 2 });

  await page.screenshot({
    path: '/app/output/final_poster.png',
    fullPage: true,
    type: 'png'
  });

  console.log(`Rendered at ${1080}x${bodyHeight} @2x`);
  await browser.close();
})();

